        `,-1)])]),_:1})),t[11]||(t[11]=a('<h2 id="投递方式决策矩阵" tabindex="-1">投递方式决策矩阵 <a class="header-anchor" href="#投递方式决策矩阵" aria-label="Permalink to &quot;投递方式决策矩阵&quot;">​</a></h2> <p>写入时是否走 PSMX、是否还要序列化走 DDSI（网络），由运行时 reader 组合决定：</p> <table tabindex="0"><thead><tr><th>有 PSMX endpoint?</th> <th>有网络 reader?</th> <th>有本地非 PSMX reader?</th> <th>投递方式</th></tr></thead> <tbody><tr><td>否</td> <td>-</td> <td>-</td> <td>仅 UDP（DDSI）</td></tr> <tr><td>是</td> <td>否</td> <td>否</td> <td><strong>仅 PSMX</strong>（最优路径，可跳过序列化）</td></tr> <tr><td>是</td> <td>是</td> <td>否</td> <td>PSMX + UDP 双投递</td></tr> <tr><td>是</td> <td>否</td> <td>是</td> <td>PSMX + 本地 DDSI 投递</td></tr> <tr><td>是</td> <td>是</td> <td>是</td> <td>PSMX + UDP + 本地 DDSI</td></tr></tbody></table> <p>完整决策链路：</p> ',8)),(d(),s(E,null,{default:e(()=>[o(r,{id:"mermaid-560",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BCYCLONEDDS_URI%20%E7%8E%AF%E5%A2%83%E5%8F%98%E9%87%8F%5D%20--%3E%20B%5BXML%20%E9%85%8D%E7%BD%AE%E8%A7%A3%E6%9E%90%20ddsi_config_init%5D%0A%20%20%20%20B%20--%3E%20C%5BNetworkInterface%20%E2%86%92%20UDP%2FDDSI%20%E7%BD%91%E7%BB%9C%E6%A0%88%5D%0A%20%20%20%20B%20--%3E%20D%5B%22PubSubMessageExchange%20%E2%86%92%20dlopen(psmx_iox2)%3Cbr%2F%3E%E8%B0%83%E7%94%A8%20iox2_create_psmx()%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%88%9B%E5%BB%BA%20Topic%20%E6%97%B6%20%E2%86%92%20type_qos_supported%20%E6%A3%80%E6%9F%A5%E5%85%BC%E5%AE%B9%E6%80%A7%5D%0A%20%20%20%20E%20--%3E%7C%E4%B8%8D%E5%85%BC%E5%AE%B9%7C%20F%5B%E8%AF%A5%E7%AB%AF%E7%82%B9%E4%B8%8D%E5%88%9B%E5%BB%BA%20PSMX%20endpoint%20%E2%86%92%20%E4%BB%85%E8%B5%B0%20UDP%5D%0A%20%20%20%20E%20--%3E%7C%E5%85%BC%E5%AE%B9%7C%20G%5B%E5%88%9B%E5%BB%BA%20PSMX%20endpoint%5D%0A%20%20%20%20G%20--%3E%20H%5Bdds_write%20%E6%97%B6%E5%88%A4%E6%96%AD%5D%0A%20%20%20%20H%20--%3E%7C%E6%97%A0%E7%BD%91%E7%BB%9C%20reader%20%E4%B8%94%E6%97%A0%E6%9C%AC%E5%9C%B0%E9%9D%9E%20PSMX%20reader%7C%20I%5B%22use_only_psmx%20%3D%20true%3Cbr%2F%3E%E4%BB%85%E9%80%9A%E8%BF%87%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98%E6%8A%95%E9%80%92%22%5D%0A%20%20%20%20H%20--%3E%7C%E6%9C%89%E5%85%B6%E4%BB%96%20reader%7C%20J%5BPSMX%20%E6%8A%95%E9%80%92%20%2B%20%E5%BA%8F%E5%88%97%E5%8C%96%E5%90%8E%E7%BB%8F%20DDSI%20%E6%8A%95%E9%80%92%5D%0A"})]),fallback:e(()=>[...t[6]||(t[6]=[i(`
